{"implementation":"import math


def solve(case):
    if not isinstance(case, dict):
        raise ValueError("case must be an object")
    if "threshold" not in case or "calls" not in case:
        raise ValueError("case is missing required fields")

    threshold = case["threshold"]
    calls = case["calls"]
    if isinstance(threshold, bool) or not isinstance(threshold, (int, float)) or not math.isfinite(threshold):
        raise ValueError("threshold must be a finite number")
    if not isinstance(calls, list):
        raise ValueError("calls must be an array")

    required = (
        "call_id",
        "loss_without_call",
        "loss_with_call",
        "prediction_tokens",
        "parseable",
    )
    validated = []
    for call in calls:
        if not isinstance(call, dict) or any(key not in call for key in required):
            raise ValueError("call is missing required fields")

        call_id = call["call_id"]
        loss_without = call["loss_without_call"]
        loss_with = call["loss_with_call"]
        prediction_tokens = call["prediction_tokens"]
        parseable = call["parseable"]

        if not isinstance(call_id, str):
            raise ValueError("call_id must be a string")
        for loss in (loss_without, loss_with):
            if isinstance(loss, bool) or not isinstance(loss, (int, float)) or not math.isfinite(loss):
                raise ValueError("losses must be finite numbers")
        if isinstance(prediction_tokens, bool) or not isinstance(prediction_tokens, int) or prediction_tokens < 0:
            raise ValueError("prediction_tokens must be a nonnegative integer")
        if not isinstance(parseable, bool):
            raise ValueError("parseable must be a boolean")

        validated.append((call_id, loss_without, loss_with, prediction_tokens, parseable))

    accepted_call_ids = []
    diagnostics = []
    for call_id, loss_without, loss_with, prediction_tokens, parseable in validated:
        future_token_weight = 1.0 / max(1, prediction_tokens)
        weighted_without = loss_without * future_token_weight
        weighted_with = loss_with * future_token_weight
        normalized_gain = weighted_without - weighted_with
        accepted = parseable and normalized_gain >= threshold
        if accepted:
            accepted_call_ids.append(call_id)
        diagnostics.append({
            "accepted": accepted,
            "call_id": call_id,
            "normalized_gain": round(normalized_gain, 6),
        })

    return {"accepted_call_ids": accepted_call_ids, "diagnostics": diagnostics}
"}
